interface AuthorBadgesProps {
  identity_badge?: IdentityBadge | null;
  identity_badges?: IdentityBadge[] | null;
  /** Compact scenes (feed list): only the official platform mark renders. */
  officialIconOnly?: boolean;
}

/**
 * Author identity marks, mirroring the platform front AuthorBadges:
 * - prefers the identity_badges array (0-2 marks), falls back to identity_badge;
 * - "verified" is retired and never rendered;
 * - official renders the orange platform mark, hover "平台官方 / Platform Official";
 * - resource_maintainer renders the wrench mark, hover "资源维护者 / Resource Maintainer";
 * - unknown codes render nothing; officialIconOnly hides everything but official;
 * - renders null (no placeholder) when there is nothing to show.
 */
export default function AuthorBadges({
  identity_badge,
  identity_badges,
  officialIconOnly = false,
}: AuthorBadgesProps) {
  const { t } = useTranslation();

  const identities = (
    identity_badges?.length
      ? identity_badges
      : identity_badge
      ? [identity_badge]
      : []
  ).filter((badge) => badge && badge.code !== "verified");

  const visibleIdentities = officialIconOnly
    ? identities.filter((badge) => badge.code === "official")
    : identities;

  if (!visibleIdentities.length) return null;

  return (
    <>
      {visibleIdentities.map((badge) => {
        if (badge.code === "official") {
          return (
            <Tooltip key={badge.code} title={t("authorBadges.official")}>
              <span className={styles.authorBadge}>
                <PlatformIcon />
              </span>
            </Tooltip>
          );
        }
        if (badge.code === "resource_maintainer") {
          return (
            <Tooltip
              key={badge.code}
              title={t("authorBadges.resourceMaintainer")}
            >
              <span className={styles.authorBadge}>
                <MaintainerIcon />
              </span>
            </Tooltip>
          );
        }
        return null;
      })}
    </>
  );
}
